        for field in ("purpose", "next_action"):
            if not isinstance(p.get(field), str):
                problems.append(f"{name}: {field} must be a string")
        for field in ("started", "first_step_done", "parked_until"):
            if p.get(field) not in (None, "") and not _is_iso_date(p.get(field)):
                problems.append(f"{name}: {field} must be YYYY-MM-DD, got {p.get(field)!r}")
        if "receiver" in p and not isinstance(p["receiver"], str):
            problems.append(f"{name}: receiver must be a string")
        elif isinstance(p.get("receiver"), str) and re.fullmatch(r"me\W*", p["receiver"].strip().lower()):
            problems.append(f"{name}: receiver 'me' needs a one-line reason, e.g. 'me: <why>'")
        if "drive_folder" in p and not isinstance(p["drive_folder"], str):
            problems.append(f"{name}: drive_folder must be a string")
        parent = p.get("parent")
        if parent is not None:
            if parent == name:
                problems.append(f"{name}: cannot be its own parent")
            elif parent not in names:
                problems.append(f"{name}: parent {parent!r} is not a project")
        if p.get("status") == "merged" and not parent:
            problems.append(f"{name}: merged needs a parent")
        charter = p.get("charter")
        if charter is not None:
            if not isinstance(charter, dict):
                problems.append(f"{name}: charter must be an object")
            else:
                dates = [("finish_by", charter.get("finish_by"))]
                dates += [(f"step '{s.get('name')}' due", s.get("due")) for s in charter.get("steps") or []]
                dates += [(f"step '{s.get('name')}' done", s.get("done"))
                          for s in charter.get("steps") or [] if s.get("done") is not None]
                for label, value in dates:
                    if value not in (None, "") and not _is_iso_date(value):
                        problems.append(f"{name}: charter {label} must be YYYY-MM-DD, got {value!r}")
        if p.get("status") == "active" and p.get("lane") in LANES and isinstance(p.get("rank"), int):
            lane_ranks = ranks_seen.setdefault(p["lane"], set())
            if p["rank"] in lane_ranks:
                problems.append(f"{name}: duplicate rank {p['rank']} in lane {p['lane']}")
            lane_ranks.add(p["rank"])
    for i in data.get("ideas", []):
        if not isinstance(i.get("pitch"), str) or not i.get("pitch"):
            problems.append("idea with missing/empty pitch")
        if i.get("status") not in IDEA_STATUSES:
            problems.append(f"idea '{i.get('pitch', '?')[:30]}': bad status")
    if problems:
        raise RegistryError("; ".join(problems))


def load_registry(path: Path) -> dict:
    if not path.exists():
        raise RegistryError(f"registry not found: {path}")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as e:
        raise RegistryError(f"registry unreadable: {e}") from e
    validate(data)
    return data


def _temp_path(path: Path) -> Path:
    """Scratch file for an atomic save.

    The name carries the pid: the CLI, the board and the `project` skill are
    separate processes writing this same path, and a shared fixed temp name lets
    one process rename the other's file out from under it (FileNotFoundError).
    It stays a sibling of the target, which os.replace needs to be atomic.
    """
    return path.with_name(f"{path.name}.{os.getpid()}.tmp")


def save_registry(path: Path, data: dict) -> None:
    validate(data)
    if path.exists():
        shutil.copy2(path, path.with_suffix(path.suffix + ".bak"))
    payload = json.dumps(data, indent=2, ensure_ascii=False) + "\n"
    tmp = _temp_path(path)
    tmp.write_text(payload, encoding="utf-8")
    # atomic on the same filesystem. On Windows it fails with WinError 5 while any other
    # handle has the target open (the board's 3 s poll, a virus scan), so retry briefly.
    for attempt in range(20):
        try:
            os.replace(tmp, path)
            return
        except PermissionError:
            if attempt == 19:
                raise
            time.sleep(0.05)


def add_idea(data: dict, pitch: str, source: str = "") -> dict:
    idea = {
        "captured_at": _dt.datetime.now().isoformat(timespec="seconds"),
        "pitch": pitch,
        "source": source,
        "status": "inbox",
    }
    data.setdefault("ideas", []).append(idea)
    return idea


def add_update(data: dict, name: str, note: str, next_action: str | None = None) -> dict:
    for p in data.get("projects", []):
        if p["name"].lower() == name.lower():
            p.setdefault("updates", []).append(
                {"date": _dt.date.today().isoformat(), "note": note}
            )
            if next_action:
                p["next_action"] = next_action
            p["curated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
            return p
    raise RegistryError(f"no project named '{name}'")


def set_stage(data: dict, name: str, stage: str) -> dict:
    if stage not in STAGES:
        raise RegistryError(f"stage must be one of {STAGES}")
    for p in data.get("projects", []):
        if p["name"].lower() == name.lower():
            p["stage"] = stage
            p.setdefault("updates", []).append(
                {"date": _dt.date.today().isoformat(), "note": f"stage → {stage}"}
            )
            p["curated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
            return p
    raise RegistryError(f"no project named '{name}'")


def mark_done(data: dict, target: str, step: int | None = None, date: str | None = None,
              skip: str | None = None) -> str:
    """Mark a charter step (project + --step 1-4) or a slate checkpoint done.

    Clearing a nag has to be one command, or the timer gets ignored.
    Checkpoints match by exact name, else by a unique case-insensitive substring.
    `skip` closes a checkpoint that will not happen (e.g. a report not sent) without
    recording a false done date: it sets `skipped` {date, reason} and leaves `done` empty.
    """
    date = date or _dt.date.today().isoformat()
    if not _is_iso_date(date):
        raise RegistryError(f"date must be YYYY-MM-DD, got {date!r}")
    if skip is not None and (step is not None or not skip.strip()):
        raise RegistryError("--skip needs a reason and applies to checkpoints only, not project steps")
    if step is not None:
        for p in data.get("projects", []):
            if p["name"].lower() == target.lower():
                steps = (p.get("charter") or {}).get("steps") or []
                if not steps and step == 1:
                    # no charter (side/tool work): step 1 is the 7-day rule's first step
                    p["first_step_done"] = date
                    p.setdefault("updates", []).append({"date": date, "note": "step 1 done (first step)"})
                    p["curated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
                    return f"{p['name']} step 1 (first step)"
                if not 1 <= step <= len(steps):
                    raise RegistryError(f"{p['name']}: step must be 1-{len(steps)}")
                steps[step - 1]["done"] = date
                p.setdefault("updates", []).append(
                    {"date": date, "note": f"step {step} done: {steps[step - 1]['name']}"})
                p["curated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
                return f"{p['name']} step {step} ({steps[step - 1]['name']})"
        raise RegistryError(f"no project named '{target}'")
    checkpoints = ((data.get("meta") or {}).get("slate") or {}).get("checkpoints") or []
    matches = [c for c in checkpoints if c.get("name", "").lower() == target.lower()]
    if not matches:
        matches = [c for c in checkpoints if target.lower() in c.get("name", "").lower()]
    if len(matches) != 1:
        found = ", ".join(c["name"] for c in matches) or "none"
        raise RegistryError(f"'{target}' must match exactly one checkpoint (matched: {found}); "
                            "for a project step pass --step")
    if skip is not None:
        matches[0]["skipped"] = {"date": date, "reason": skip.strip()}
        return f"{matches[0]['name']} (skipped: {skip.strip()})"
    matches[0]["done"] = date
    return matches[0]["name"]


def main(argv: list[str] | None = None) -> int:
    registry_path = Path(__file__).resolve().parent / "portfolio.json"

    parser = argparse.ArgumentParser(prog="portfolio.py")
    subparsers = parser.add_subparsers(dest="command", required=True)

    idea_parser = subparsers.add_parser("add-idea")
    idea_parser.add_argument("pitch")
    idea_parser.add_argument("--source", default="")

    update_parser = subparsers.add_parser("add-update")
    update_parser.add_argument("name")
    update_parser.add_argument("note")
    update_parser.add_argument("--next-action", default=None)

    stage_parser = subparsers.add_parser("set-stage")
    stage_parser.add_argument("name")
    stage_parser.add_argument("stage")

    slate_parser = subparsers.add_parser("slate-check")
    slate_parser.add_argument("--json", action="store_true")
    slate_parser.add_argument("--today", default=None)
    slate_parser.add_argument("--registry", default=None)

    week_parser = subparsers.add_parser("week-report")
    week_parser.add_argument("--end", default=None)
    week_parser.add_argument("--out", default=None, help="directory; writes <end>.md there")
    week_parser.add_argument("--registry", default=None)

    cross_parser = subparsers.add_parser("crosswalk", help="report drift between registry, DEV and Drive")
    cross_parser.add_argument("--json", action="store_true")
    cross_parser.add_argument("--registry", default=None)
    cross_parser.add_argument("--dev-root", default=None, help="default: the folder holding project-triage")
    cross_parser.add_argument("--drive-root", default=None,
                              help="default: PORTFOLIO_DRIVE_ROOT, else this machine's Drive path")

    seven_parser = subparsers.add_parser("seven-day", help="7-day rule: report, or --apply to pause expired starts")
    seven_parser.add_argument("--apply", action="store_true")
    seven_parser.add_argument("--json", action="store_true")
    seven_parser.add_argument("--today", default=None)

    card_parser = subparsers.add_parser(
        "card-check", help="closeout: resume card + gaps for every project touched since a date")
    card_parser.add_argument("--since", default=None, help="YYYY-MM-DD (default: today)")
    card_parser.add_argument("--project", action="append", help="check this project (repeatable) instead")
    card_parser.add_argument("--registry", default=None)
    card_parser.add_argument("--dev-root", default=None, help="default: the folder holding project-triage")
    card_parser.add_argument("--json", action="store_true")
    sweep_parser = subparsers.add_parser("sweep", help="Friday sweep: paused rows untouched 30+ days, oldest first")
    sweep_parser.add_argument("--limit", type=int, default=10)
    sweep_parser.add_argument("--registry", default=None)
    sweep_parser.add_argument("--json", action="store_true")
    decide_parser = subparsers.add_parser("sweep-decide", help="revive / keep (parked 90 days) / archive a swept row")
    decide_parser.add_argument("name")
    decide_parser.add_argument("decision", choices=["revive", "keep", "archive"])
    decide_parser.add_argument("--next-action", default=None)
    decide_parser.add_argument("--receiver", default=None)
    status_parser = subparsers.add_parser(
        "set-status", help="start / park / finish a project (slate cap + 7-day clock, same as the board)")
    status_parser.add_argument("name")
    status_parser.add_argument("status", choices=sorted(PROJECT_STATUSES))
    status_parser.add_argument("--note", default=None, help="one-line update to log with it")
    receiver_parser = subparsers.add_parser("set-receiver", help="name who a project is for")
    receiver_parser.add_argument("name")
    receiver_parser.add_argument("receiver")

    done_parser = subparsers.add_parser("mark-done")
    done_parser.add_argument("target", help="project name (with --step) or checkpoint name")
    done_parser.add_argument("--step", type=int, default=None)
    done_parser.add_argument("--date", default=None)
    done_parser.add_argument("--skip", default=None, metavar="REASON",
                             help="close a checkpoint that will not happen, with the reason")

    args = parser.parse_args(argv)

    try:
        if args.command == "slate-check":
            import slate  # lazy: tests copy portfolio.py alone into scratch dirs
            path = Path(args.registry) if args.registry else registry_path
            today = slate.parse_date(args.today) if args.today else _dt.date.today()
            if today is None:
                raise RegistryError(f"--today must be YYYY-MM-DD, got {args.today!r}")
            result = slate.check(load_registry(path), today)
            print(json.dumps(result, indent=2) if args.json else slate.format_report(result))
            return 0
        if args.command == "week-report":
            import slate  # lazy, same reason as slate-check
            path = Path(args.registry) if args.registry else registry_path
            end = slate.parse_date(args.end) if args.end else _dt.date.today()
            if end is None:
                raise RegistryError(f"--end must be YYYY-MM-DD, got {args.end!r}")
            md = slate.week_report(load_registry(path), end)
            if args.out:
                out = Path(args.out)
                out.mkdir(parents=True, exist_ok=True)
                target = out / f"{end.isoformat()}.md"
                target.write_text(md, encoding="utf-8")
                print(f"wrote {target}")
            else:
                print(md)
            return 0
        if args.command == "crosswalk":
            import crosswalk  # lazy, same reason as slate-check
            path = Path(args.registry) if args.registry else registry_path
            dev_root = Path(args.dev_root) if args.dev_root else registry_path.parent.parent
            drive_root = Path(args.drive_root) if args.drive_root else crosswalk.default_drive_root()
            result = crosswalk.check(load_registry(path), dev_root, drive_root)
            print(json.dumps(result, indent=2) if args.json else crosswalk.format_report(result))
            return 0
        data = load_registry(registry_path)
        if args.command == "seven-day":
            import seven_day
            today = _dt.date.fromisoformat(args.today) if args.today else _dt.date.today()
            before = json.dumps(data, sort_keys=True)
            seven_day.stamp_started(data, today)
            paused = seven_day.apply(data, today) if args.apply else []
            problems = seven_day.check(data, today)
            if json.dumps(data, sort_keys=True) != before:
                save_registry(registry_path, data)
            if args.json:
                print(json.dumps({"paused": paused, "problems": problems}, indent=2))
            else:
                print(f"7-day rule: {len(paused)} paused, {len(problems)} on the clock")
                for n in paused:
                    print(f"  PAUSED   {n}")
                for p in problems:
                    print(f"  {p['level']:<8} {p['project']}: {p['message']}")
            return 0
        if args.command == "set-receiver":
            for p in data["projects"]:
                if p["name"].lower() == args.name.lower():
                    p["receiver"] = args.receiver.strip()
                    save_registry(registry_path, data)
                    print(f"{p['name']}: receiver {p['receiver']}")
                    return 0
            raise RegistryError(f"no project named '{args.name}'")
        if args.command == "card-check":
            # closeout's card check (PM design Decision 9): every project touched since
            # --since gets its resume card printed with the gaps that keep it from being true.
            import cards, landed  # lazy, same reason as slate-check
            path = Path(args.registry) if args.registry else registry_path
            data = load_registry(path)
            dev_root = Path(args.dev_root) if args.dev_root else path.resolve().parent.parent
            since = args.since or _dt.date.today().isoformat()
            ledger = landed.read_ledgers()
            local_tz = _dt.datetime.now().astimezone().tzinfo
            start = _dt.datetime.fromisoformat(since).replace(tzinfo=local_tz).isoformat()
            names = args.project or cards.touched_since(data, ledger, start)
            built = cards.build_cards(data, dev_root, ledger)
            rows = {p["name"]: p for p in data["projects"]}
            out = []
            for n in names:
                if n not in rows:
                    raise RegistryError(f"unknown project: {n}")
                said = cards.status_date(dev_root, rows[n]) if n not in built else None
                out.append({"name": n, "card": built.get(n),
                            "gaps": cards.card_gaps(rows[n], built.get(n), since, said)})
            if args.json:
                print(json.dumps(out, indent=2))
            else:
                bad = sum(1 for o in out if o["gaps"])
                print(f"cards: {len(out)} touched since {since}, {bad} with gaps")
                for o in out:
                    print()
                    print(cards.format_card(rows[o["name"]], o["card"], o["gaps"]))
            return 0
        if args.command in ("sweep", "sweep-decide"):
            # the Friday sweep (PM design Decision 6); lazy like slate-check, and catch the
            # imported module's RegistryError by name (see set-status)
            import landed, sweep
            today = _dt.date.today()
            if args.command == "sweep":
                path = Path(args.registry) if args.registry else registry_path
                d, ledger = load_registry(path), landed.read_ledgers()
                rows = sweep.candidates(d, ledger, today, args.limit)
                pending = sweep.pending_count(d, ledger, today)
                print(json.dumps({"pending": pending, "rows": rows}, indent=2) if args.json
                      else sweep.format_report(rows, pending))
                return 0
            try:
                sweep.decide(data, args.name, args.decision, today,
                             next_action=args.next_action, receiver=args.receiver)
            except sweep.RegistryError as e:
                raise RegistryError(str(e)) from None
            save_registry(registry_path, data)
            print(f"sweep: {args.name} → {args.decision}")
            return 0
        if args.command == "set-status":
            # The board's Start/Park/Done path, so terminal and page share the slate-cap
            # check and the 7-day clock. Lazy for the same reason as slate-check. Run as
            # a script, this module is __main__, so board_ops raises a different
            # RegistryError class: catch that one by name.
            import board_ops
            try:
                board_ops.patch_project(data, args.name, status=args.status,
                                        note=args.note, today=_dt.date.today().isoformat())
            except board_ops.RegistryError as e:
                raise RegistryError(str(e)) from None
            save_registry(registry_path, data)
            print(f"status set: {args.name} → {args.status}")
            return 0
        if args.command == "mark-done":
            what = mark_done(data, args.target, step=args.step, date=args.date, skip=args.skip)
            save_registry(registry_path, data)
            print(f"done: {what}")
            return 0
        if args.command == "add-idea":
            add_idea(data, args.pitch, source=args.source)
            save_registry(registry_path, data)
            inbox_count = sum(1 for i in data.get("ideas", []) if i.get("status") == "inbox")
            print(f"idea captured ({inbox_count} in inbox)")
        elif args.command == "add-update":
            add_update(data, args.name, args.note, next_action=args.next_action)
            save_registry(registry_path, data)
            print(f"updated {args.name}")
        elif args.command == "set-stage":
            set_stage(data, args.name, args.stage)
            save_registry(registry_path, data)
            print(f"stage set: {args.name} → {args.stage}")
    except RegistryError as e:
        print(f"[error] {e}", file=sys.stderr)
        return 2
    return 0


